/// #[macro_export]
/// macro_rules! print_message {
///     () => {
///         println!("{}", crate::MESSAGE);
///     };
/// }
/// pub const MESSAGE: &str = "Hello!";
/// ```
/// Use instead:
/// ```no_run
/// #[macro_export]
/// macro_rules! print_message {
///     () => {
